mapper.insert:
INSERT INTO time_table
(yy, mm, dayname, period_no, start_time, end_time, class_no, unit_no, grade_no, user_no, created_at)
values (#{yy}, #{mm}, #{dayname}, #{periodNo}, #{startTime},  #{endTime}, #{classNo}, #{unitNo}, #{gradeNo}, #{userNo}, CURRENT_TIMESTAMP);

INSERT INTO time_table_assign
(student_no, time_table_no, week)
values (#{studentNo}, #{timeTableNo}, #{weekNo});

mapper.select:
SELECT COUNT(*) 
FROM time_table_assign 
WHERE time_table_no = #{timeTableNo}
